import { extractBankTxnCode } from '../../../../../utils/extractBankTxnCode';
import type {
  BankStatementImportBatchLine,
  BankStatementImportStatementLine,
} from '../../../../../services/kt/bankStatementImportModels';

/** Chi tiết phân bổ IMP — dòng + mã GD (thu/chi chỉ hiện số dòng). */
export function formatImpStatementAllocLabel(line: BankStatementImportStatementLine): string {
  const gd = extractBankTxnCode(line.description, line.referenceCode);
  const name = (line.counterpartyName || '').trim();
  const parts = [`#${line.rowIndex}`];
  if (gd) parts.push(`GD ${gd}`);
  if (name) parts.push(name);
  return parts.join(' · ');
}

export function formatImpBatchAllocLabel(line: BankStatementImportBatchLine): string {
  const gd = (line.ftNumber || '').trim();
  const name = (line.beneficiaryName || '').trim();
  const parts = [`Lô ${line.batchRef || line.lineIndex}`];
  if (gd) parts.push(`GD ${gd}`);
  if (name) parts.push(name);
  return parts.join(' · ');
}
